#include "editor.hpp"
namespace touch::ui {
namespace {
void outline(ImDrawList* draw,CanvasRect r,ImU32 tint){draw->AddRectFilled(r.min,{r.max.x,r.min.y+1},tint);draw->AddRectFilled({r.min.x,r.max.y-1},r.max,tint);draw->AddRectFilled(r.min,{r.min.x+1,r.max.y},tint);draw->AddRectFilled({r.max.x-1,r.min.y},r.max,tint);}
void cable(ImDrawList* draw,const std::vector<ImVec2>& points,ImU32 tint,float width){for(size_t i=1;i<points.size();++i){auto a=points[i-1],b=points[i];draw->AddRectFilled({std::round(std::min(a.x,b.x)-width/2),std::round(std::min(a.y,b.y)-width/2)},{std::round(std::max(a.x,b.x)+width/2),std::round(std::max(a.y,b.y)+width/2)},tint);}}
}
void Editor::draw_grid(ImDrawList* draw){if(!grid)return;float step=theme::grid*zoom;for(float x=std::fmod(std::fmod(pan.x,step)+step,step);x<canvas_size.x;x+=step)draw->AddRectFilled({std::round(origin.x+x),origin.y},{std::round(origin.x+x)+1,origin.y+canvas_size.y},theme::panel);for(float y=std::fmod(std::fmod(pan.y,step)+step,step);y<canvas_size.y;y+=step)draw->AddRectFilled({origin.x,std::round(origin.y+y)},{origin.x+canvas_size.x,std::round(origin.y+y)+1},theme::panel);}
CanvasHit Editor::draw_nodes(ImDrawList* draw,bool hovered){CanvasHit hit;auto mouse=ImGui::GetIO().MousePos;for(auto edge:document.graph.edges){auto path=cable_points(port_position(edge.from,true),port_position(edge.to,false));ImU32 tint=theme::muted;try{tint=theme::signal_color(port_signal(document.graph,services.registry,edge.from,true));}catch(...){}if(wire_original&&wire_original->to==edge.to)tint=theme::rgb(0x666666);cable(draw,path,tint,2);for(size_t i=1;i<path.size();++i)if(hovered&&segment_distance(mouse,path[i-1],path[i])<6)hit.edge=edge;}
std::vector<const Node*> nodes;for(auto& n:document.graph.nodes)nodes.push_back(&n);std::stable_sort(nodes.begin(),nodes.end(),[&](auto a,auto b){return document.selected.contains(a->id)<document.selected.contains(b->id);});
for(auto node:nodes){auto bounds=node_bounds(node->id);if(!bounds.overlaps({origin,{origin.x+canvas_size.x,origin.y+canvas_size.y}}))continue;auto descriptor=services.registry.find(node->type);bool selected=document.selected.contains(node->id),error=monitor.errors.contains(node->id),active=node->id==document.graph.preview||node->id==document.graph.video||node->id==document.graph.audio;ImU32 border=error?theme::error:selected?theme::select:theme::rgb(0x5c5c5c);draw->AddRectFilled(bounds.min,bounds.max,theme::panel);
if(!reroute(*node)){float bottom=bounds.min.y+theme::header*zoom;draw->AddRectFilled(bounds.min,{bounds.max.x,bottom},theme::rgb(0x373737));draw->AddRectFilled({bounds.min.x,bottom},{bounds.max.x,bottom+1},theme::border);if(zoom>=.5f){float y=bounds.min.y+std::round((theme::header*zoom-7)*.5f);theme::pixel_text(draw,{bounds.min.x+6,y},descriptor?descriptor->label:node->type,selected?theme::select:theme::text,bounds.max.x-bounds.min.x-(active||error?22:12));if(active||error)theme::pixel_text(draw,{bounds.max.x-10,y},error?"!":"*",error?theme::error:theme::select,6);}}
outline(draw,bounds,border);if(hovered&&bounds.contains(mouse)){hit.node=node->id;hit.input.reset();hit.output.reset();}
size_t inputs=descriptor?descriptor->inputs.size()+descriptor->params.size():node->input_keys.size(),outputs=descriptor?descriptor->outputs.size():node->output_keys.size();for(bool output:{false,true})for(size_t i=0;i<(output?outputs:inputs);++i){Port port{node->id,i};auto at=port_position(port,output);Signal signal=Signal::Control;if(descriptor)signal=output?descriptor->outputs[i]:i<descriptor->inputs.size()?descriptor->inputs[i]:Signal::Control;auto tint=theme::signal_color(signal);float size=std::clamp(std::round(5*zoom),4.f,8.f);CanvasRect socket{{at.x-size,at.y-size*.5f},{at.x+size,at.y+size*.5f}};bool connected=std::any_of(document.graph.edges.begin(),document.graph.edges.end(),[&](auto e){return output?e.from==port:e.to==port;});draw->AddRectFilled(socket.min,socket.max,connected||!output?tint:theme::panel);if(!connected&&output)outline(draw,socket,tint);if(descriptor&&!reroute(*node)&&zoom>=.7f){auto label=port_label(*descriptor,output,i);float width=std::min(float(label.size()*6),std::max(0.f,(bounds.max.x-bounds.min.x)*.5f-12));theme::pixel_text(draw,{at.x+(output?-width-9:9),at.y-3},label,theme::muted,width);}if(hovered&&std::hypot(mouse.x-at.x,mouse.y-at.y)<10){if(output)hit.output=port;else hit.input=port;}}
}
if(wire){auto from=port_position(wire->port,wire->output),to=mouse;std::optional<Endpoint> target;if(wire->output&&hit.input)target=Endpoint{*hit.input,false};if(!wire->output&&hit.output)target=Endpoint{*hit.output,true};if(target)to=port_position(target->port,target->output);if(!wire->output)std::swap(from,to);ImU32 tint=theme::select;try{tint=theme::signal_color(port_signal(document.graph,services.registry,wire->port,wire->output));}catch(...){}cable(draw,cable_points(from,to),tint,3);}
return hit;}
}
